export type { Speaker, MessageType };

export interface Choice {
  /** Stable runtime identity; localization may change text but never this key. */
  id?: string;
  text: string;
  nextId: string;
  statEffect?: 'none';
  trustDelta?: number;
  memoryDelta?: number;
  attachmentDelta?: number;
  acceptFarewell?: boolean;
  finalChoice?: FinalChoice;
  timedResponse?: TimedResponse;
  timedProof?: TimedProof;
  finalFarewellTone?: FinalFarewellTone;
  relationshipStrainDelta?: number;
  n7ProofSucceeded?: boolean;
  firstMessageCorrect?: boolean;
  visibilityCondition?:
    | 'legacy-ef-both'
    | 'legacy-ef-any'
    | 'legacy-ef-none'
    | 'n7-proof-succeeded'
    | 'legacy-prologue-alien-choice';
}

export type InteractionCondition = {
  kind: SpecialInteractionKind;
  routeKey: string;
};

export type InteractionPrerequisite = {
  key: string;
  value: string | number | boolean;
};

export interface StoryNode {
  id: string;
  speaker: Speaker;
  type: MessageType;
  content: string;
  choices?: Choice[];
  choiceTimeoutMs?: number;
  timeoutNextId?: string;
  image?: string;
  delay?: number;
  nextId?: string;
  isGlitch?: boolean;
  glitchLevel?: GlitchLevel;
  memoryAnchor?: MemoryAnchorId;
  requiresAnchor?: MemoryAnchorId;
  contactStage?: ContactStage;
  displayOptionContext?: string;
  archiveEntry?: string;
  externalEntry?: string;
  recordVariable?: string;
  inputVariable?: string;
  inputMinLength?: number;
  inputMaxLength?: number;
  inputAutoFocus?: boolean;
  specialInputNextIds?: Record<string, string>;
  interactionKind?: SpecialInteractionKind;
  interactionNextIds?: Record<string, string>;
  interactionAttempt?: 1 | 2;
  interactionStage?: 'first' | 'final' | 'damaged_seventh';
  interactionPrerequisite?: InteractionPrerequisite;
  interactionCondition?: InteractionCondition;
  conditionElseNextId?: string;
  directCondition?: InteractionPrerequisite;
  directConditionNextId?: string;
  stateWrites?: Record<string, string | number | boolean>;
  dynamicNextKey?: 'lastStableCheckpoint';
  inputSubmitText?: string;
  displayName?: string;
  speakerIdentity?: NovaSpeakerIdentity;
  deliveryEvent?: DeliveryEventKey;
  archiveUnlock?: string | string[];
  endingUnlock?: EndingId;
}

